  buildings.forEach(label);residents.forEach(residentLabel);ctx.fillStyle='#7b9e92';ctx.font='italic 15px Georgia';ctx.textAlign='center';const sea=iso(18.1,10);ctx.save();ctx.translate(sea.x+13,sea.y);ctx.rotate(-.45);ctx.fillText('the quiet coast',0,0);ctx.restore();
